# Seller Agreement feature: new gate page, acceptance API route,
# and vendor layout update enforcing the gate for all vendors.
# Delivered via base64 to guarantee correct UTF-8 regardless of console encoding.

New-Item -ItemType Directory -Force -Path "src\app\vendor\agreement" | Out-Null
New-Item -ItemType Directory -Force -Path "src\app\api\vendor\agree-to-seller-agreement" | Out-Null

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\vendor\agreement\page.tsx"), $bytes)
Write-Host "WRITTEN: src\app\vendor\agreement\page.tsx" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\vendor\agreement\VendorAgreementPage.tsx"), $bytes)
Write-Host "WRITTEN: src\app\vendor\agreement\VendorAgreementPage.tsx" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\api\vendor\agree-to-seller-agreement\route.ts"), $bytes)
Write-Host "WRITTEN: src\app\api\vendor\agree-to-seller-agreement\route.ts" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\vendor\(protected)\layout.tsx"), $bytes)
Write-Host "WRITTEN: src\app\vendor\(protected)\layout.tsx" -ForegroundColor Green

Write-Host "`nAll 4 files written." -ForegroundColor Cyan
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan